def shortest_path(n, edges, src, dst):
    # Enumerate simple paths with DFS and take minimum length
    g = {i: [] for i in range(n)}
    for a, b in edges:
        g[a].append(b)
        g[b].append(a)
    best = [float('inf')]
    def dfs(u, seen, dist):
        if u == dst:
            best[0] = min(best[0], dist)
            return
        for v in g[u]:
            if v not in seen:
                dfs(v, seen | {v}, dist + 1)
    dfs(src, {src}, 0)
    return -1 if best[0] == float('inf') else best[0]

