from collections import defaultdict, deque

def shortest_path(n, edges, src, dst):
    if src == dst:
        return 0
    g = defaultdict(list)
    for a, b in edges:
        g[a].append(b)
        g[b].append(a)
    q = deque([(src, 0)])
    seen = {src}
    while q:
        u, dist = q.popleft()
        for v in g[u]:
            if v in seen:
                continue
            if v == dst:
                return dist + 1
            seen.add(v)
            q.append((v, dist + 1))
    return -1
